function validate([s, k]) {
  if (s.length < 1 || s.length > 16) return 's needs 1 to 16 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (k < 1 || k > 16) return 'k is between 1 and 16.';
  return null;
}

