function minDeletion(s, k) {
  const counts = new Map();
  for (const ch of s) {
    counts.set(ch, (counts.get(ch) ?? 0) + 1);
  }
  const sizes = [...counts.values()].sort((a, b) => a - b);
  let deletions = 0;
  for (let i = 0; i < sizes.length - k; i++) {
    deletions += sizes[i];
  }
  return deletions;
}

brute:
function minDeletion(s, k) {
  // Try every set of positions to keep and count the different letters that remain.
  const n = s.length;
  let best = n;
  for (let keep = 0; keep < 1 << n; keep++) {
    const letters = new Set();
    let kept = 0;
    for (let i = 0; i < n; i++) {
      if (keep & (1 << i)) { letters.add(s[i]); kept++; }
    }
    if (letters.size <= k) best = Math.min(best, n - kept);
  }
  return best;
}

