function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const length = large ? 16 : pick(1, 10);
  const span = pick(1, large ? 26 : 6);
  const first = pick(0, 26 - span);
  let s = '';
  for (let i = 0; i < length; i++) {
    // rand() * rand() favours the first letters, so the letters appear with different frequencies.
    s += String.fromCharCode(97 + first + Math.floor(rand() * rand() * span));
  }
  return [s, pick(1, large ? 16 : 6)];
}
